window.RP_SESSION={"id":"S-48c1d37cdc30","messages":[{"id":"RP-II-0099664","time":"2026-05-11T21:14:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099665","time":"2026-05-11T21:14:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"다그닥 다그닥.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099666","time":"2026-05-11T21:15:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"팔켄하인 영지를 벗어나 남쪽으로 향하기 시작한지 반나절이 지났습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099667","time":"2026-05-11T21:15:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"추격대를 꾸려서 쫒아오고 있겠지만 잠시 쉴 여유 정도는 있겠지요.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099668","time":"2026-05-11T21:15:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"고생했다. 록시.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099669","time":"2026-05-11T21:16:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"두그닥, 두그닥\n\n두그\n\n     닥\n\n두\n   그\n      닥...\n\n\"...푸르륵.\"\n\n록시의 발걸음이 천천히 느려지고, 숨을 몰아쉬듯 투레질을 했습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099670","time":"2026-05-11T21:16:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"늙은 말의 목을 두어번 쓰다듬어주고는, 갈 길을 바라보고,\n\n다시 지나온 길을 보았습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099671","time":"2026-05-11T21:16:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"저만치 훌쩍 남았고, 저만치 훌쩍 지나왔습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099672","time":"2026-05-11T21:17:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"길 끝이 앞뒤로 아득합니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099673","time":"2026-05-11T21:17:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"- ...어쩔 거죠? -","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099674","time":"2026-05-11T21:17:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099675","time":"2026-05-11T21:17:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"- 어쩔 거냐고요? -","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099676","time":"2026-05-11T21:17:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099677","time":"2026-05-11T21:17:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"오늘따라 마음이 시끄럽습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099678","time":"2026-05-11T21:18:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"- 토르번! 어쩔 생각이냐고요. -","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099679","time":"2026-05-11T21:18:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"화들짝. 양심의 목소리가 아니라 그의 검, 카일라였습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099680","time":"2026-05-11T21:18:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...아, 미안하군. 잠시 생각하느라.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099681","time":"2026-05-11T21:18:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"천천히. 머릿속을 정리합니다.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099682","time":"2026-05-11T21:19:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...일단 집에 가서 정리해야지. 모든 진실을 이야기 하고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099683","time":"2026-05-11T21:19:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"리스양 에게 전해줄 말도 있군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099684","time":"2026-05-11T21:20:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"정리가 끝나면 스텔라 양에게 나를 파면시키라 요구할 걸세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099685","time":"2026-05-11T21:20:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"나는 그들의 짐이 되기 위해서 어설픈 용맹의 이름을 댄 게 아니야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099686","time":"2026-05-11T21:21:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"적어도 누명을 벗을 때까지는 떠나야지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099687","time":"2026-05-11T21:22:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"떠날 때 한가지 부탁 정도는 해도 되겠지.\"\n\n\"내 사비로, 어설픈 용맹에 의뢰를 할 걸세. 괴물과 팔켄하인에 대해 조사를 해달라고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099688","time":"2026-05-11T21:22:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"조사가 끝이 나면, 그제서야 길드로 돌아갈 셈이야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099689","time":"2026-05-11T21:22:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"만일 형제들의 죄가 아니라면, 나 혼자서 결착을 지을 것이고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099690","time":"2026-05-11T21:23:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그들의 죄라면 가족들과 함께 그들을 벌해야지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099691","time":"2026-05-11T21:24:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099692","time":"2026-05-11T21:24:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"너무 낙관적인 사고인가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099693","time":"2026-05-11T21:24:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"- ...글쎄요. -","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099694","time":"2026-05-11T21:24:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래도 해야지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099695","time":"2026-05-11T21:26:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래도 운명에 발버둥쳐야지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099696","time":"2026-05-11T21:26:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"\"그래도 의지에 답해야지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099697","time":"2026-05-11T21:27:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"그래도,\n\n아무래도,\n\n확실히.","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099698","time":"2026-05-11T21:27:00+09:00","room":"RP II","name":"토르번","profile":"타냐 잉게누스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"RP-II-0099699","time":"2026-05-11T21:27:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
